            </Flex>

            <DashKitDnDWrapper>
                <DashKit
                    config={config}
                    editMode={editMode}
                    onChange={onChange}
                    onDrop={handleDrop}
                    onItemEdit={handleItemEdit}
                />
                {editMode && (
                    <ActionPanel
                        items={actionPanelItems}
                        toggleAnimation
                    />
                )}
            </DashKitDnDWrapper>
        </div>
    );
}
